fn upgrade_item(&mut self, rnd, player, game:&dyn AbstractGame, context) -> Option<(usize,usize)>   // lib.rs:1193~1207
  // L1194
  if player.info.item_builds.is_empty() {                          // +0x4f0 == 0
      // L1205 — 레거시 위임(sret 그대로 전달)
      return game_ai::upgrade_item(self.version, rnd, player, game, context)   // lib.rs:1603 · version/game poison
  }
  // L1195
  item_list = &context.item_list                                    // +0x30
  (build_slot, inventory_index) = Self::item_v26_slot(player, item_list.as_slice())?   // 외부 None(+8==usize::MAX) → None
  // L1196
  let Some(inv) = inventory_index else { return None }             // 태그 0 → None: 슬롯 아이템을 아직 안 들고 있음 = 구매 소관(buy_item)
  // L1198
  item = self.item_v26(rnd, player, context, build_slot, Some(inv))?   // tag 상수 1 · payload = inv
  // L1199
  if item_list[item].tier() == 0 { return None }                   // L1200 — tier 0 은 승급 결과가 아님(vtable+0x70 · 색인 bounds 패닉)
  // L1203
  Some((inv, item))                                                 // +8 = inv · +16 = item · +0 = 1

★buy_item 과의 쌍: 같은 item_v26_slot → item_v26 파이프라인을 (inventory_index Some 필수, tier≠0 채택) 으로 뒤집은 것. 결과 (인벤 슬롯, 새 아이템) 을 게임이 '그 슬롯을 그 아이템으로 교체' 로 소비한다고 읽힘(소비처 = game_core AiAgent 호출부 · 미확인).
